import React, { ChangeEvent, PropsWithChildren, useId } from "react";
import FormGroup, { FormGroupProps } from "../Form/FormGroup";
import useControlled from "../../lib/hooks/useControlled";
import { CommonProps } from "../helperTypes";

export type Props = PropsWithChildren<{
  /** The default value for an uncontrolled group */
  defaultValue?: any[];
  /** The name of the group */
  name?: string;
  /** The callback for when the input checked status changes */
  onChange?: (event: ChangeEvent<HTMLInputElement>, value: any) => void;
  /** customise the props passed to the root FormGroup component */
  rootProps?: FormGroupProps;
  /** If `true`, radios will be shown in a row */
  row?: boolean;
  /** If provided, the group will work in a controlled way */
  value?: any[];
}>;

export type CheckboxGroupProps = Props & CommonProps;

const CheckboxGroup = ({
  children,
  defaultValue = [],
  name: nameProp,
  onChange,
  rootProps,
  row,
  value: valueProp,
  ...rest
}: CheckboxGroupProps) => {
  const defaultId = `checkboxgroup-${useId()}`;
  const name = nameProp || defaultId;
  const [value, setValueState] = useControlled({
    value: valueProp,
    defaultValue,
  });

  const handleChange = (e: ChangeEvent<HTMLInputElement>) => {
    const newValue = e.target.checked
      ? [...value, e.target.value]
      : value.filter((v: any) => v !== e.target.value);
    setValueState(newValue);
    if (onChange) {
      onChange(e, newValue);
    }
  };

  const formGroupProps = { ...rest, ...rootProps };
  return (
    <FormGroup role="group" row={row} {...formGroupProps}>
      {React.Children.map(children, (child) => {
        if (!React.isValidElement(child)) {
          return null;
        }
        if (process.env.NODE_ENV !== "production") {
          if (child.type === React.Fragment) {
            console.warn(
              "The CheckboxGroup component doesn't accept a Fragment as a child. Consider providing an array instead."
            );
          }
        }

        const childProps = child.props as any;

        return React.cloneElement<any>(child, {
          name,
          checked: value.indexOf(childProps.value) !== -1,
          onChange: handleChange,
        });
      })}
    </FormGroup>
  );
};

export default CheckboxGroup;
